unattend.settings:

    {{ hostname }}
    {% if timezone %}{{ timezone }}{% endif %}
    {# Optional ProductKey (operator or Server GVLK). Do NOT use
       Microsoft-Windows-Setup UserData/WillShowUI here — empty Key in
       specialize fails with "could not apply unattend settings".
       Evaluation guests must omit this (see windows_evaluation branch). #}
    {% if product_key and not windows_evaluation %}{{ product_key }}{% endif %}




            1
            Enable built-in Administrator for GuestOS local admin
            wscript.exe //B //nologo C:\Windows\System32\GuestOS-RunHidden.vbs cmd.exe /c net user Administrator /active:yes


            2
            GuestOS: mark unattend-created user for OOBE
            wscript.exe //B //nologo C:\Windows\System32\GuestOS-RunHidden.vbs cmd.exe /c reg add "HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Setup\OOBE" /v UnattendCreatedUser /t REG_DWORD /d 1 /f{% if windows_evaluation %} & reg add "HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Setup\OOBE" /v SetupDisplayedProductKey /t REG_DWORD /d 1 /f{% endif %}


            3
            GuestOS: disable first-logon animation; UAC for built-in Administrator
            wscript.exe //B //nologo C:\Windows\System32\GuestOS-RunHidden.vbs cmd.exe /c reg add "HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System" /v EnableFirstLogonAnimation /t REG_DWORD /d 0 /f & reg add "HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System" /v FilterAdministratorToken /t REG_DWORD /d 1 /f


            4
            GuestOS: register SYSTEM AtStartup setup task
            wscript.exe //B //nologo C:\Windows\System32\GuestOS-RunHidden.vbs C:\Windows\System32\GuestOS-RegisterSetup.cmd



{# Offline Domain Join: the blob carries domain, machine account and its
   password, so no credentials appear here and no DC contact is needed.
   Omitted when provisioning was not possible — setup.ps1 then joins with
   Add-Computer after OOBE. Credential-based JoinDomain is not used; see
   docs/UNATTENDED_JOIN_INVESTIGATION.md. #}
{% if odj_account_data %}



            {{ odj_account_data }}



{% endif %}

settings.component:
true 1 true true true true
{{ administrator_password }} true
{# Win10/11 client OOBE still prompts for a user name unless a LocalAccounts entry exists (HideLocalAccountScreen is Server-only). GuestOSOobe is removed by setup.ps1 account cleanup. #}
GuestOSOobe GuestOS Administrators
{{ administrator_password }} true
{# No AutoLogon / FirstLogonCommands: GuestOS-Setup (SYSTEM AtStartup) runs setup.ps1. #}
